<template>
  <div class="studio">
    <header class="topbar"><a class="brand" href="/">◈ <span>叙幕 <small>简易工作台 · STORY STUDIO</small></span></a><span class="top-note">把你心里的故事，变成一部短片。</span><button @click="settingsOpen=!settingsOpen" :disabled="!project">模型与费用设置</button><a href="/classic">切换到原版工作台 ↗</a></header>
    <div class="layout">
      <aside class="sidebar"><div class="side-heading">我的片场 <button class="icon" @click="create(false)" aria-label="新建项目">＋</button></div><button v-for="p in projects" :key="p.id" :class="['project',{active:project?.drama_id===p.id}]" @click="open(p.id)"><span>▣</span><div>{{p.title}}<small>30秒短片 · 本机保存</small></div></button><div class="sidebar-bottom"><button @click="create(true)">打开「雨停之前」示例</button><p>示例包含剧本与分镜，不含AI成片。生成素材需配置自己的模型。</p><span>基于 LocalMiniDrama · MIT</span></div></aside>
      <main>
        <div v-if="error" class="notice error" role="alert">{{error}} <button class="icon" @click="error=''">×</button></div>
        <div v-if="message" class="notice" role="status">{{message}}</div>
        <section v-if="!project" class="welcome"><div class="eyebrow">YOUR STORY, FIRST FRAME</div><h1>从一句故事<br>到第一声「开拍」。</h1><p>口述想法，预览剧本与人物，再逐镜制作。<br>你决定每一步，预算始终看得见。</p><div class="actions"><button class="primary" @click="create(false)">＋ 创建我的第一部短片</button><button @click="create(true)">先看看示例</button></div><div class="welcome-spec"><span>16:9 电影画幅</span><span>30秒完整叙事</span><span>最高 ¥50 项目预算</span></div></section>
        <template v-if="project">
          <section class="project-heading"><div><div class="eyebrow">LOCAL FILM PROJECT / {{String(project.drama_id).padStart(3,'0')}}</div><h1>{{doc.title}}</h1><p>真人电影质感 · 16:9 · {{duration}} / 30秒 · 版本 {{project.revision}}</p></div><div class="budget"><small>剩余可用预算</small><strong>¥{{yuan(project.ledger.remaining_micros)}}</strong><span>已用 / 预留 ¥{{yuan(project.ledger.committed_micros)}} · 上限 ¥{{yuan(project.budget_micros)}}</span></div></section>
          <nav class="steps"><button v-for="(label,i) in steps" :key="label" :class="{selected:step===i}" @click="step=i"><span>{{i+1}}</span>{{label}}</button></nav>
          <section v-if="settingsOpen" class="panel settings"><h2>一次设置，持续创作</h2><p>密钥只保存在本机后端。生成时会向所选云端服务发送必要素材。价格请按供应商账单填写费用上界，不预设虚假报价。</p><div class="model-grid"><div v-for="kind in kinds" :key="kind" class="model-card"><h3>{{kindNames[kind]}}</h3><label>已配置的模型<select v-model.number="settings[kind].config_id" @change="pickModel(kind)"><option :value="null">请选择</option><option v-for="m in models.filter(m=>m.service_type===kind || (kind==='image' && m.service_type==='storyboard_image'))" :key="m.id" :value="m.id">{{m.name}} {{m.configured?'':'（未启用）'}}</option></select></label><label>精确模型标识<input v-model="settings[kind].model" placeholder="填写供应商的模型ID"></label><template v-if="kind==='text'"><label>输入 ¥ / 百万Token<input v-model.number="settings[kind].input_per_million" type="number" min="0" step="0.01"></label><label>输出 ¥ / 百万Token<input v-model.number="settings[kind].output_per_million" type="number" min="0" step="0.01"></label></template><label v-else>费用上界 ¥ / {{kind==='image'?'张':'秒'}}<input v-model.number="settings[kind][kind==='image'?'per_image':'per_second']" type="number" min="0" step="0.001"></label><label v-if="kind==='video'">视频分辨率<select v-model="settings.video.resolution"><option>720p</option><option>1080p</option><option>480p</option></select></label><details><summary>添加{{kindNames[kind]}}连接</summary><label>接口地址<input v-model="connection[kind].base_url" :placeholder="baseUrls[kind]"></label><label>模型ID<input v-model="connection[kind].model" :placeholder="modelHints[kind]"></label><label>API Key（可选，本地模型可留空）<input v-model="connection[kind].api_key" type="password" autocomplete="new-password"></label><button @click="addModel(kind)">保存连接</button></details></div></div><div class="actions"><button class="primary" @click="saveSettings">保存模型与费用</button><span>切换视频模型或价格后，需要重新完成5秒试镜验收。</span></div></section>
          <section v-if="step===0" class="panel"><div class="section-title"><div><h2>01 / 先说说你的故事</h2><p>不需要写提示词。人物、冲突和结局，交给编剧模型整理。</p></div><button @click="versionsOpen=!versionsOpen; loadVersions()">版本历史</button></div><textarea class="story-input" v-model="storyDraft" placeholder="例如：雨夜的修表铺里，一位父亲收到了女儿带来的旧表……" aria-label="故事内容"></textarea><div class="actions"><button :class="{recording}" @click="toggleRecording" :disabled="busy">{{recording?'■ 结束录音并转写':'● 口述故事'}}</button><label class="file-button">上传录音<input type="file" accept="audio/*,.webm" @change="uploadAudio"></label><button @click="saveStory" :disabled="busy || storyDraft===doc.story">保存故事</button><button class="primary" @click="generate('story')" :disabled="busy || !doc.story || doc.shots.length>0">生成剧本与分镜</button></div><p class="hint">录音最长5分钟，10MB以内；转写结果先预览，再替换故事。已有分镜时使用局部微调。</p><article v-if="doc.script" class="script"><div class="section-title"><h3>分场剧本</h3><button @click="edit('story')">编辑 / AI微调</button></div><p>{{doc.script}}</p></article><div v-if="versionsOpen" class="versions"><h3>内容历史 · 恢复不会删除素材或费用记录</h3><button v-for="v in versions" :key="v.revision" @click="restore(v.revision)">版本 {{v.revision}} · {{v.reason}}</button><p v-if="!versions.length">还没有历史版本。</p></div></section>
          <section v-if="step===1" class="panel"><div class="section-title"><div><h2>02 / 确定人物与空间</h2><p>先定妆，再拍摄。服装、声音、场景会传递给每个相关镜头。</p></div></div><div class="asset-grid"><article v-for="asset in assets" :key="asset.key" class="asset-card"><div class="asset-image"><img v-if="asset.image" :src="url(asset.image)" :alt="asset.name"><span v-else>{{asset.group==='characters'?'人物定妆':'场景空镜'}}<small>等待第一张参考图</small></span></div><div class="card-body"><h3>{{asset.name}}</h3><p>{{asset.appearance || asset.description}}</p><p v-if="asset.voice" class="hint">声音：{{asset.voice}}</p><div class="actions"><button @click="edit(asset.key)">编辑 / 微调</button><button class="primary" @click="generate('image',asset.key)" :disabled="busy">生成参考图</button><label class="file-button">上传图片<input type="file" accept="image/*" @change="uploadImage($event,asset.key)"></label></div></div></article></div><p v-if="!assets.length" class="empty">先在「故事」步骤生成剧本，或从侧栏打开示例。</p></section>
          <section v-if="step===2 || step===3" class="panel"><div class="section-title"><div><h2>{{step===2?'03 / 让每个镜头有目的':'04 / 开拍，先试一个镜头'}}</h2><p>{{step===2?'逐镜确定画面与对白，满意后再付费生成视频。':'先做5秒对白试镜，核对人物、声音、口型和账单，通过后再拍其余镜头。'}}</p></div><button v-if="step===2" class="primary" @click="approvePreview" :disabled="busy">{{doc.preview_approved?'✓ 预览已确认':'确认剧本与全部参考图'}}</button><span v-else class="badge">{{project.pilot_task?'✓ 试镜已验收':'待完成试镜验收'}}</span></div><div class="shot-grid"><article v-for="(shot,i) in doc.shots" :key="shot.id" class="shot-card"><div class="frame"><video v-if="step===3 && shot.video" :src="url(shot.video)" controls preload="metadata"></video><img v-else-if="shot.image" :src="url(shot.image)" :alt="shot.description"><span v-else class="placeholder">第 {{i+1}} 镜 · 等待静帧</span><b>{{String(i+1).padStart(2,'0')}} / {{shot.duration}}s</b></div><div class="card-body"><span v-if="shot.stale" class="stale">内容已变化 · 请检查关联素材</span><p v-if="shot.video_prompt_needs_review" class="stale">片段描述已修改，请编辑提示词或检查后确认。<button @click="reviewVideoPrompt(shot.id)">已检查，提示词与描述一致</button></p><h3>{{shot.description}}</h3><p class="dialogue">“{{shot.dialogue || '无对白'}}”</p><small>{{shot.camera}}</small><div class="actions"><button @click="edit('shots:'+shot.id)">编辑 / 微调</button><button v-if="step===2" class="primary" @click="generate('image','shots:'+shot.id)" :disabled="busy">生成静帧</button><label v-if="step===2" class="file-button">上传静帧<input type="file" accept="image/*" @change="uploadImage($event,'shots:'+shot.id)"></label><template v-else><button class="primary" @click="generate('video','shots:'+shot.id,!project.pilot_task)" :disabled="busy || !doc.preview_approved">{{project.pilot_task?'生成视频':'生成5秒试镜'}}</button><button v-if="shot.stale && shot.video" @click="acknowledge(shot.id)">检查后沿用</button></template></div></div></article></div><p v-if="!doc.shots.length" class="empty">剧本生成后，分镜会出现在这里。</p></section>
          <section v-if="step===4" class="panel"><div class="section-title"><div><h2>05 / 剪成你的第一部短片</h2><p>调整顺序、入出点和音量后导出。采用镜头内原生对白；字幕按镜头显示。</p></div><button class="primary" @click="generate('export')" :disabled="busy">合成 MP4 与字幕</button></div><div v-for="(shot,i) in doc.shots" :key="shot.id" class="timeline-row"><span>{{i+1}}</span><img v-if="shot.image" :src="url(shot.image)" alt="分镜预览"><div><strong>{{shot.description}}</strong><small>{{shot.enabled===false?'不参与成片':`${shot.trim_in || 0}s → ${shot.trim_out ?? shot.duration}s · 音量 ${shot.volume ?? 1}`}}</small></div><button @click="moveShot(i,-1)" :disabled="i===0">↑</button><button @click="moveShot(i,1)" :disabled="i===doc.shots.length-1">↓</button><button @click="edit('shots:'+shot.id)">剪辑参数</button></div><video v-if="doc.export_url" class="final-video" :src="doc.export_url" controls></video><div class="actions"><a v-if="doc.export_url" class="primary file-button" :href="doc.export_url" download="短片.mp4">下载成片</a><a :href="apiBase+'/projects/'+project.drama_id+'/export-project'" class="file-button">下载工程与费用记录</a></div></section>
          <section class="panel tasks"><div class="section-title"><div><h2>生成记录与候选版本</h2><p>失败或状态不明的任务仍占用预留费用。按账单核对后释放，已完成的素材可重复选用。</p></div><button @click="refresh">刷新</button></div><p v-if="!project.ledger.tasks.length" class="empty">还没有生成任务。先保存模型连接与费用，再开始创作。</p><article v-for="t in project.ledger.tasks" :key="t.id" class="task"><div class="task-info"><span :class="['status',t.state]">{{states[t.state] || t.state}}</span><strong>{{kindNames[t.kind] || '成片导出'}} · {{t.target}}</strong><small>{{t.config_snapshot.model || '本机 FFmpeg'}} · {{new Date(t.created_at).toLocaleString()}}</small><p v-if="t.error" class="task-error">{{t.error}}</p><small v-if="t.provider_task_id">供应商编号：{{t.provider_task_id}}</small></div><div class="task-actions"><span>{{t.actual_micros==null?'预留':'核算'}} ¥{{yuan(t.actual_micros ?? t.reserved_micros)}}</span><button v-if="t.state==='completed'" @click="viewCandidate(t)">预览 / 选择版本</button><button v-if="t.kind==='video' && t.state==='unknown' && (t.provider_task_id || t.result?.remote_url)" @click="resumeTask(t)">继续查询原任务</button><button v-if="['completed','unknown','reconciled'].includes(t.state)" @click="modal={type:'reconcile',task:t,actual:t.actual_micros==null?'':t.actual_micros/1000000,note:t.reconciliation_note || ''}">账单对账</button><button v-if="t.kind==='video' && t.input.pilot && t.state==='completed'" @click="modal={type:'pilot',task:t,checks:{}}">验收试镜</button></div></article></section>
        </template>
      </main>
    </div>
    <div v-if="modal" class="overlay" @click.self="modal=null"><section class="dialog" role="dialog" aria-modal="true" :aria-label="modalTitle"><div class="section-title"><h2>{{modalTitle}}</h2><button class="icon" @click="modal=null" aria-label="关闭">×</button></div>
      <template v-if="modal.type==='edit'"><p>只修改当前对象，保存前预览影响范围。</p><label v-for="(value,key) in modal.changes" :key="key">{{labels[key] || key}}<select v-if="key==='enabled'" v-model="modal.changes[key]"><option :value="true">参与成片</option><option :value="false">跳过</option></select><select v-else-if="key==='scene'" v-model="modal.changes[key]"><option v-for="s in doc.scenes" :key="s.id" :value="s.id">{{s.name}}</option></select><select v-else-if="key==='characters'" v-model="modal.changes[key]" multiple><option v-for="c in doc.characters" :key="c.id" :value="c.id">{{c.name}}</option></select><input v-else-if="['duration','trim_in','trim_out','volume'].includes(key)" v-model.number="modal.changes[key]" type="number" step="0.1"><textarea v-else v-model="modal.changes[key]" rows="2"></textarea></label><div class="actions"><button class="primary" @click="previewEdit">预览修改</button></div><hr><label>用一句话微调当前对象<textarea v-model="modal.instruction" placeholder="例如：只把这个镜头的运镜改成缓慢推近"></textarea></label><button @click="refine">让AI生成修改建议</button></template>
      <template v-if="modal.type==='diff'"><p>将影响镜头：{{modal.preview.affected.join('、') || '无关联镜头变化'}}。旧版本会保留。</p><div class="diff-grid"><div><h3>修改前</h3><pre>{{pretty(modal.preview.before)}}</pre></div><div><h3>修改后</h3><pre>{{pretty(modal.preview.after)}}</pre></div></div><button class="primary" @click="applyEdit">应用此修改</button></template>
      <template v-if="modal.type==='quote'"><p>本次最多预留 <strong>¥{{yuan(modal.quote.estimated_micros)}}</strong>，可用预算 ¥{{yuan(modal.quote.remaining_micros)}}。</p><p>点击后向配置的供应商发送素材。费用上界依赖你填写的价格；最终以供应商账单为准。</p><button class="primary" @click="submitQuote" :disabled="busy || modal.quote.estimated_micros>modal.quote.remaining_micros">确认生成</button></template>
      <template v-if="modal.type==='candidate'"><video v-if="modal.task.result.media_type==='video' || modal.task.kind==='export'" :src="url(modal.task.result.path || modal.task.result.video)" controls class="candidate-media"></video><img v-else-if="modal.task.result.media_type==='image'" :src="url(modal.task.result.path)" class="candidate-media" alt="生成候选图"><template v-else-if="modal.task.result.changes"><h3>修改前</h3><pre>{{pretty(modal.task.result.before)}}</pre><h3>修改建议</h3><pre>{{pretty(modal.task.result.changes)}}</pre></template><pre v-else>{{modal.task.result.transcript || pretty(modal.task.result.document)}}</pre><div class="actions"><button class="primary" @click="applyCandidate">使用此版本</button><a v-if="modal.task.kind==='export'" :href="url(modal.task.result.subtitles)" download>下载 SRT</a></div></template>
      <template v-if="modal.type==='reconcile'"><p>填写本任务供应商账单金额。状态不明的任务对账后会结束，之后才可重新提交。</p><label>实际费用（元）<input v-model.number="modal.actual" type="number" min="0" step="0.001"></label><label>账单依据<textarea v-model="modal.note" placeholder="账单日期、订单号、确认未收费等依据"></textarea></label><button class="primary" @click="reconcile">保存账单核对</button></template>
      <template v-if="modal.type==='pilot'"><video :src="url(modal.task.result.path)" controls class="candidate-media"></video><p>先完成该任务的账单对账，再逐项确认实际观看结果。</p><label v-for="(text,key) in {identity:'人物外观、服装与参考图一致',dialogue:'有清晰中文对白，声音符合角色设定',lips:'对白与口型无明显错位',motion:'动作自然，无明显肢体畸变'}" :key="key" class="check"><input v-model="modal.checks[key]" type="checkbox">{{text}}</label><button class="primary" @click="approvePilot">记录验收，开放其余镜头生成</button></template>
    </section></div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
const apiBase='/api/v1/studio', projects=ref([]), project=ref(null), models=ref([]), step=ref(0), settingsOpen=ref(false), storyDraft=ref(''), error=ref(''), message=ref(''), busy=ref(false), modal=ref(null), versionsOpen=ref(false), versions=ref([])
const kinds=['text','asr','image','video'], kindNames={text:'剧本 / 文本',asr:'口述转写',image:'图片',video:'视频'}, steps=['故事','角色与场景','分镜','视频','成片']
const states={reserved:'已预留',running:'生成中',polling:'等待供应商',completed:'已完成',unknown:'待查询 / 对账',failed:'失败',reconciled:'已对账'}
const labels={story:'故事梗概',script:'分场剧本',name:'名称',appearance:'人物外观与服装',voice:'声音设定',motivation:'人物动机',description:'画面 / 场景描述',dialogue:'人物对白',camera:'景别与运镜',image_prompt:'静帧画面要求',video_prompt:'视频表演要求',duration:'生成时长（秒）',trim_in:'剪辑入点（秒）',trim_out:'剪辑出点（秒）',volume:'音量（0–2）',enabled:'是否参与成片',characters:'出场角色（可多选）',scene:'场景'}
const baseUrls={text:'https://api.deepseek.com',asr:'https://dashscope.aliyuncs.com/compatible-mode/v1',image:'https://ark.cn-beijing.volces.com/api/v3',video:'https://ark.cn-beijing.volces.com/api/v3'}
const modelHints={text:'填写已开通的 DeepSeek 模型ID',asr:'qwen3-asr-flash',image:'填写已开通的 Seedream 模型ID',video:'填写支持对白的 Seedance 模型ID'}
const blankSettings=()=>Object.fromEntries(kinds.map(k=>[k,{config_id:null,model:'',...(k==='video'?{resolution:'720p'}:{})}]))
const settings=ref(blankSettings()),connection=ref(Object.fromEntries(kinds.map(k=>[k,{base_url:'',model:'',api_key:''}]))), recording=ref(false)
const doc=computed(()=>project.value?.document || {}),duration=computed(()=>doc.value.shots?.reduce((n,s)=>n+s.duration,0) || 0)
const assets=computed(()=>['characters','scenes'].flatMap(group=>(doc.value[group] || []).map(x=>({...x,group,key:group+':'+x.id}))))
const modalTitle=computed(()=>({edit:'调整当前内容',diff:'确认修改范围',quote:'确认生成费用',candidate:'候选版本',reconcile:'按账单核对费用',pilot:'5秒对白试镜验收'}[modal.value?.type]))
const yuan=n=>(Number(n || 0)/1000000).toFixed(3),url=file=>file?.startsWith('/static/')?file:'/static/'+file
function pretty(value) { if(Array.isArray(value))return value.map(pretty).join('、');if(value && typeof value==='object')return Object.entries(value).filter(([key])=>!['id','stale'].includes(key)).map(([key,val])=>(labels[key] || {title:'片名',scenes:'场景',shots:'分镜',image:'参考图',video:'视频'}[key] || key)+'：'+pretty(val)).join('\n\n');return typeof value==='boolean'?(value?'是':'否'):String(value ?? '') }
async function uploadImage(event,target) { const file=event.target.files[0];if(file)await safe(async()=>{const form=new FormData();form.append('image',file);form.append('target',target);form.append('revision',project.value.revision);await api(path()+'/upload-image','POST',form);await refresh();message.value='参考图已保存，关联镜头已标记。'});event.target.value='' }
async function api(path,method='GET',body) { const res=await fetch(apiBase+path,{method,headers:body instanceof FormData?{}:{'Content-Type':'application/json'},...(body?{body:body instanceof FormData?body:JSON.stringify(body)}:{})});const data=await res.json();if(!res.ok)throw new Error(data.error?.message || data.error || '请求失败');return data }
async function safe(fn) { error.value='';busy.value=true;try{return await fn()}catch(e){error.value=e.message;return null}finally{busy.value=false} }
const path=()=>'/projects/'+project.value.drama_id
async function refresh() { if(!project.value)return;const id=project.value.drama_id;const next=await api(path());if(project.value?.drama_id!==id)return;if(storyDraft.value===project.value.document.story)storyDraft.value=next.document.story;project.value=next }
async function open(id) { if(recording.value){error.value='请先结束录音，再切换项目';return}await safe(async()=>{const next=await api('/projects/'+id);project.value=next;storyDraft.value=next.document.story;settings.value={...blankSettings(),...next.settings};step.value=0;localStorage.setItem('studio-project',String(id));modal.value=null}) }
async function create(example) { if(recording.value){error.value='请先结束录音，再创建项目';return} await safe(async()=>{const p=await api('/projects','POST',{example});projects.value=await api('/projects');project.value=p});if(project.value)await open(project.value.drama_id) }
async function saveStory() { await safe(async()=>{await api(path()+'/apply','POST',{revision:project.value.revision,target:'story',changes:{story:storyDraft.value}});await refresh();message.value='故事已保存。'}) }
async function addModel(kind) { await safe(async()=>{const result=await api('/models','POST',{kind,...connection.value[kind]});settings.value[kind].config_id=result.id;settings.value[kind].model=connection.value[kind].model;connection.value[kind].api_key='';models.value=await api('/models');message.value='连接已保存，请填写价格并保存模型与费用。'}) }
function pickModel(kind) { const m=models.value.find(m=>m.id===settings.value[kind].config_id);if(m)settings.value[kind].model=m.model[0] || '' }
async function saveSettings() { await safe(async()=>{await api(path()+'/settings','PUT',{settings:settings.value});await refresh();settingsOpen.value=false;message.value='模型与费用已保存。'}) }
function edit(target) { const [group,id]=target.split(':');const item=target==='story'?{story:doc.value.story,script:doc.value.script}:doc.value[group].find(x=>x.id===id);const changes=Object.fromEntries(Object.entries(item).filter(([k])=>labels[k]));if(group==='shots')Object.assign(changes,{trim_in:item.trim_in || 0,trim_out:item.trim_out ?? item.duration,volume:item.volume ?? 1,enabled:item.enabled!==false});modal.value={type:'edit',target,changes:JSON.parse(JSON.stringify(changes)),revision:project.value.revision,instruction:''} }
async function previewEdit() { await safe(async()=>{const m=modal.value;const preview=await api(path()+'/preview','POST',m);modal.value={...m,type:'diff',preview}}) }
async function applyEdit() { await safe(async()=>{await api(path()+'/apply','POST',modal.value);modal.value=null;await refresh();message.value='修改已保存，旧版本可以恢复。'}) }
async function generate(kind,target='story',pilot=false,instruction='') { await safe(async()=>{if(storyDraft.value!==doc.value.story && kind==='story')throw new Error('请先保存故事');const body={kind,target,pilot,instruction,revision:project.value.revision,request_key:crypto.randomUUID()};const quote=await api(path()+'/quote','POST',body);modal.value={type:'quote',body,quote}}) }
async function refine() { const m=modal.value;await generate('refine',m.target,false,m.instruction) }
async function submitQuote() { const m=modal.value;await safe(async()=>{await api(path()+'/tasks','POST',m.body);modal.value=null;await refresh();message.value='任务已提交；生成记录中可以查看进度和候选版本。'}) }
function viewCandidate(task) { modal.value={type:'candidate',task} }
async function applyCandidate() { await safe(async()=>{await api(path()+'/tasks/'+modal.value.task.id+'/apply','POST',{revision:project.value.revision});modal.value=null;await refresh();message.value='已采用所选版本。'}) }
async function reviewVideoPrompt(shotId) { await safe(async()=>{await api(path()+'/review-video-prompt','POST',{revision:project.value.revision,shot_id:shotId});await refresh()}) }
async function approvePreview() { await safe(async()=>{await api(path()+'/approve-preview','POST',{revision:project.value.revision});await refresh();step.value=3}) }
async function acknowledge(id) { await safe(async()=>{await api(path()+'/acknowledge','POST',{revision:project.value.revision,shots:[id]});await refresh()}) }
async function moveShot(i,delta) { await safe(async()=>{const ids=doc.value.shots.map(s=>s.id);[ids[i],ids[i+delta]]=[ids[i+delta],ids[i]];await api(path()+'/reorder','POST',{revision:project.value.revision,shots:ids});await refresh()}) }
async function loadVersions() { await safe(async()=>{versions.value=await api(path()+'/versions')}) }
async function restore(version) { await safe(async()=>{await api(path()+'/restore','POST',{version,revision:project.value.revision});await refresh();await loadVersions()}) }
async function resumeTask(t) { await safe(async()=>{await api(path()+'/tasks/'+t.id+'/resume','POST',{});await refresh()}) }
async function reconcile() { await safe(async()=>{const m=modal.value;await api(path()+'/tasks/'+m.task.id+'/reconcile','POST',{actual:m.actual,note:m.note});modal.value=null;await refresh()}) }
async function approvePilot() { await safe(async()=>{const m=modal.value;await api(path()+'/tasks/'+m.task.id+'/approve-pilot','POST',{checks:m.checks});modal.value=null;await refresh()}) }
let recorder, stream, recordTimer, pollTimer
async function sendAudio(blob) { await safe(async()=>{const form=new FormData();form.append('audio',blob,'story.webm');form.append('revision',project.value.revision);form.append('request_key',crypto.randomUUID());await api(path()+'/transcribe','POST',form);await refresh();message.value='录音已提交转写，完成后请预览文字。'}) }
async function uploadAudio(event) { const file=event.target.files[0];if(file)await sendAudio(file);event.target.value='' }
async function toggleRecording() {
  if(recording.value){recorder.stop();return}
  await safe(async()=>{if(!settings.value.asr.config_id || settings.value.asr.per_second==null)throw new Error('先保存语音模型与每秒价格，再录音');stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{recording.value=false;clearTimeout(recordTimer);stream.getTracks().forEach(t=>t.stop());sendAudio(new Blob(chunks,{type:recorder.mimeType}))};recorder.start();recording.value=true;recordTimer=setTimeout(()=>recorder.stop(),290000)})
}
onMounted(async()=>{await safe(async()=>{projects.value=await api('/projects');models.value=await api('/models')});const saved=Number(localStorage.getItem('studio-project'));if(projects.value.some(p=>p.id===saved))await open(saved);pollTimer=setInterval(()=>{if(project.value)refresh().catch(e=>{error.value=e.message})},4000)})
onBeforeUnmount(()=>{clearInterval(pollTimer);clearTimeout(recordTimer);if(recorder && recording.value){recorder.onstop=null;recorder.stop()}stream?.getTracks().forEach(t=>t.stop())})
</script>

